using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Reduction;

internal sealed class FiniteEdgeProbeCorrespondenceDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Loop-corrected labelled endpoint probes identify graph connectivity with actual Hilbert components.",
        H("FiniteEdgeProbeCorrespondence"),
        Blocks(
            Paragraph(Text("Let V be a finite coordinate type, E an arbitrary edge-label type, and u and v its endpoint maps. The probe indices are the disjoint sum of V and E. A vertex a contributes its coordinate basis vector. An edge with equal endpoints contributes that same basis vector; an edge with distinct endpoints contributes the sum of its two basis vectors divided by the square root of two. The anchor of a vertex is itself and the anchor of an edge is its first endpoint. No labels are identified: repeated edges, reverse-labelled edges and loops are separate indices. Vertices without incident edges remain basis probes, and the construction includes an empty edge family. Even an empty V is permitted when the endpoint maps exist.")),
            Describe.Lean(
                DescribeId.Create("construction"),
                DeclarationHandle.Create("D5/S3/Quantum/Reduction/FiniteEdgeProbeCorrespondence.construction"),
                H("Normalized spanning probes and exact components"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For every finite V with decidable equality, every type E and endpoint maps u and v, all the explicit probes have squared norm one and their complex linear span is the entire coordinate space. For any two probe indices, the equivalence closure of their nonzero inner products holds if and only if their anchors are connected by the equivalence closure of the original endpoint generators. For every probe index j, the actual hilbertComponent of its quotient class is exactly the coordinate subspace on the vertices connected to its anchor. Its complex finrank is the cardinality of that vertex subtype.")),
                    Paragraph(Text("Each nonzero coordinate of a probe lies in the graph class of its anchor. A nonzero inner product has a nonzero summand, hence a shared coordinate; this proves one implication of the component correspondence. Conversely, each original edge gives a path from its first endpoint basis probe through its labelled edge probe to its second endpoint basis probe. Every edge probe is linked to its anchor, so this proves the other implication. For the subspace equality, each component probe vanishes outside the graph class, while every basis vector in that class belongs to the actual probe component. The coordinate basis restricted to that class is linearly independent, yielding the exact dimension. The number of labelled configurations is not used as a dimension."))),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("restricted-endpoint-closure"),
                DeclarationHandle.Create("D5/S3/Quantum/Reduction/FiniteEdgeProbeCorrespondence.restricted_endpoint_closure"),
                H("Endpoint closure under a change of carrier"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For any ambient type A, subset S, edge-label type E, maps u and v into S, and a and b in S, connectivity generated by the lifted endpoints in S is equivalent to connectivity generated by their values in A. There is no finiteness or nonemptiness assumption. Mapping a subtype path to values gives the forward direction. For the reverse direction, a is a fallback value defining a retraction from A onto S. It fixes every endpoint and transports each generator and each equivalence-closure constructor back to S."))),
                DescribeRole.Theorem),
            Paragraph(Text("For the actual FIB support, take V to be ActiveVertex(c), E to be Fin(3t-3), and the lifted endpoints to be the two values of chosenPair(c,e), together with their endpoint activity proofs. The ambient generator says that chosenPair(c,e) equals the ordered endpoint pair. Product extensionality identifies it with the two endpoint equations in Connected. The restriction theorem therefore identifies the lifted generated equivalence with supportSetoid(c) on subtype values, which is activeSetoid(c). This correspondence is derived from chosenPair; it is not a definitional equality between the two generated relations. When t is at least two, 3t is nonzero, so the ambient residue type is finite and its active subtype is finite. The label zero exists because 3t-3 is positive, and its first endpoint supplies an active vertex, proving nonemptiness. Balanced is unnecessary for this construction; it enters only further consequences such as the existing at-most-two active component bound.")),
            Paragraph(Text("Apply exact_component_port_dimension to the explicit normalized spanning menu. In its existing flagged coherent-port model, the minimum coherent dimension is the maximum of the actual component dimensions, now identified with component vertex counts. The lower bound retains probability preservation for every original probe and every density input. Apply probe_channel_block_form only under its trace-preserving Kraus identity and the same universal probability preservation. Its cross-component terms retain the actual environment Gram coefficients; they need not vanish. Pinching is the composite of the particular constructed port. The abstract decomposition and graph-algebra background is consistent with Ortiz and Paulsen, arXiv:1412.7101v1, Theorem 3.2, and the nondisturbance background with Barnum, Hayden, Jozsa and Winter, quant-ph/0011072v2, Lemma 1. These references do not supply the explicit Lean endpoint correspondence. The native state, observer, preparation and instrument interpretation remains an additional bridge; this coordinate construction does not assert a physical realization, a QFT model or an identification of native physical constants.")))));
}
